// The `model` parameter is responsible for the communication model. initially, there is a gpt-4 model

const Gpt_Client = require('gpt4free-client');

async function main() {
  const completion = new Gpt_Client.Completion();

  await completion.create({
    model: "gpt-4-0613", // model
    messages: [{ role: 'user', content: 'hello world' }] // messages
  });

  for await (const chunk of completion) {
    console.log(chunk);
  }
}

main()